select * from (values
($s$payroll-tax$s$, 1, true, $j${"ar":"من الملتزم بتقديم الإقرار الربع سنوي المنصوص عليه بالبند (1) من المادة (15) من قانون الضريبة على الدخل رقم 91 لسنة 2005؟","en":"Who must file the quarterly return required by Article 15(1) of Income Tax Law No. 91 of 2005?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"يلتزم أصحاب الأعمال والملتزمون بدفع الإيرادات الخاضعة للضريبة، بما في ذلك الشركات والمشروعات المقامة بنظام المناطق الحرة، بتقديم إقرار ربع سنوي إلى مأمورية الضرائب المختصة في يناير وأبريل ويوليو وأكتوبر من كل عام على النموذج المعد لذلك، طبقًا لما تحدده اللائحة التنفيذية للقانون."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Employers and payers of taxable income, including companies and projects operating under the free-zone regime, must file a quarterly return with the competent tax office in January, April, July and October each year, on the prescribed form, as set out in the Executive Regulations."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 2, true, $j${"ar":"ما الحالات التي يُعفى فيها الممول (الموظف أو العامل) من تقديم الإقرار الضريبي السنوي؟","en":"When is a taxpayer (employee or worker) exempt from filing an annual tax return?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"يُعفى الممول من تقديم الإقرار في الحالتين الآتيتين:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إذا اقتصر دخله على المرتبات وما في حكمها أيًّا كان مقداره."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إذا اقتصر دخله على المرتبات وما في حكمها وإيرادات الثروة العقارية، ولم يتجاوز صافي دخله السنوي منها 5000 جنيه (الشريحة المعفاة طبقًا للمادة 7 من القانون)."}]}]}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A taxpayer is exempt from filing in two cases:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where their income consists only of salaries and similar payments, whatever the amount."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where their income consists only of salaries and similar payments plus income from real estate, and their net annual income from these does not exceed EGP 5,000 (the exempt bracket under Article 7 of the Law)."}]}]}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 3, true, $j${"ar":"ما الحالات التي يلتزم فيها الممول (الموظف أو العامل) بتقديم الإقرار الضريبي السنوي؟","en":"When must a taxpayer (employee or worker) file an annual tax return?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"يلتزم الممول بتقديم إقراره الضريبي السنوي في الحالتين الآتيتين:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إذا تضمن دخله إيرادات من نشاط تجاري أو صناعي أو من نشاط مهني غير تجاري إلى جانب إيرادات المرتبات وما في حكمها، أيًّا كانت قيمة هذا الدخل."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إذا زاد دخله من المرتبات وما في حكمها وإيرادات الثروة العقارية على 5000 جنيه سنويًّا (الشريحة المعفاة طبقًا للمادة 7 من القانون)."}]}]}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A taxpayer must file an annual return in two cases:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where, alongside salary income, they also earn income from a commercial or industrial activity or from a non-commercial profession, whatever the amount."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where their combined income from salaries and real estate exceeds EGP 5,000 a year (the exempt bracket under Article 7 of the Law)."}]}]}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 4, true, $j${"ar":"ما المعاملة الضريبية لما يحصل عليه عمال اليومية من المرتبات وما في حكمها؟","en":"How are daily-wage workers taxed on salaries and similar payments?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"وحّد القانون المعاملة الضريبية للعمال العاديين وعمال اليومية، بحيث تُحدَّد الإيرادات الخاضعة للضريبة عن كل جزء من السنة تم فيه الحصول على الإيراد بنسبة مدته، وذلك بعد تحويل الإيراد الشهري إلى إيراد سنوي، مع تطبيق الشريحة المعفاة المنصوص عليها في المادة (7) وقدرها 5000 جنيه، والإعفاء الشخصي المنصوص عليه في البند (1) من المادة (13) وقدره 4000 جنيه."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Law treats regular and daily-wage workers the same way. Taxable income is determined pro rata for each part of the year in which income was earned, after annualising the monthly income, and both the EGP 5,000 exempt bracket under Article 7 and the EGP 4,000 personal allowance under Article 13(1) apply."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 5, true, $j${"ar":"هل يحق للممول (العامل أو الموظف) الاعتراض على قيمة الضريبة المخصومة منه؟ ولأي جهة يقدَّم الاعتراض؟","en":"Can an employee object to the amount of tax withheld, and to whom?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نعم، يحق له ذلك بطلب يقدَّم إلى جهة العمل التي قامت بالخصم خلال ثلاثين يومًا من تاريخ استلام المرتب. وإذا لم تكن للعامل جهة يتيسر أن يتقدم إليها بالاعتراض، فله أن يتقدم به إلى مأمورية الضرائب المختصة أو لجنة الطعن المختصة بحسب الأحوال خلال المدة نفسها."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes. The employee submits a request to the employer that made the deduction within 30 days of receiving the salary. If there is no such employer to object to, the objection may be filed, within the same period, with the competent tax office or appeal committee, as applicable."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 6, true, $j${"ar":"هل يحق لجهة العمل الاعتراض على فروق ضريبة المرتبات الناتجة عن الفحص؟","en":"Can an employer object to payroll-tax differences arising from an examination?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نعم، يحق لجهة العمل الاعتراض على فروق الضريبة الناتجة عن الفحص خلال ثلاثين يومًا من تاريخ استلام الإخطار، طبقًا لنص المادة (118) من القانون رقم 91 لسنة 2005."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes. The employer may object to tax differences arising from an examination within 30 days of receiving the notice, under Article 118 of Law No. 91 of 2005."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 7, true, $j${"ar":"هل يجوز خصم 10% مقابل الحصول على الإيراد في ظل العمل بأحكام القانون رقم 91 لسنة 2005؟","en":"Is a 10% deduction for the cost of earning income allowed under Law No. 91 of 2005?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"لم يقرر القانون رقم 91 لسنة 2005 خصم 10% مقابل الحصول على الإيراد، وإنما قرر زيادة الإعفاءات المقررة للشريحة المعفاة (5000 جنيه) والإعفاء الشخصي (4000 جنيه)."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. Law No. 91 of 2005 did not provide a 10% deduction for the cost of earning income. Instead it increased the exempt bracket (EGP 5,000) and the personal allowance (EGP 4,000)."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 8, true, $j${"ar":"ما المعاملة الضريبية للمبالغ التي يتقاضاها الممول (العامل أو الموظف) من غير جهة عمله الأصلية؟","en":"How are amounts an employee receives from an entity other than their main employer taxed?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"تخضع المبالغ التي يحصل عليها الممول (منتدبًا كان أو غير منتدب) من جهة غير جهة عمله الأصلية للضريبة على المرتبات وما في حكمها بسعر 10% ضريبة قطعية، دون خصم أي تكاليف أو خصومات أخرى؛ وبناءً على ذلك لا يتمتع من يحصل على هذه المبالغ بأي إعفاءات ضريبية عنها."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Amounts received from an entity other than the main employer, whether or not the person is seconded, are subject to salary tax at a flat final rate of 10%, with no deduction for costs or any other allowance. No tax exemptions apply to these amounts."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 9, true, $j${"ar":"ما المعاملة الضريبية لما يتقاضاه العاملون من بدل مقابل الوجبة الغذائية؟","en":"How is a meal allowance paid to employees taxed?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نصّت الفقرة (أ) من البند (5) من المادة (13) من القانون صراحةً على إعفاء الوجبة الغذائية التي تُصرف للعاملين، بشرط أن تكون عينية وجماعية. ويترتب على ذلك أنه إذا دفع صاحب العمل مبلغًا نقديًّا مقابل الوجبة، عُدّ ميزة نقدية تخضع للضريبة على المرتبات ويتحملها من صُرفت له."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Article 13(5)(a) of the Law expressly exempts meals provided to employees, provided they are in kind and provided collectively. If the employer instead pays cash in lieu of the meal, the payment is a cash benefit subject to salary tax, borne by the employee who receives it."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 10, true, $j${"ar":"ما المعاملة الضريبية لما يتقاضاه العاملون من بدل نقدي مقابل عدم استفادتهم من ميزة النقل الجماعي في ظل القانون رقم 91 لسنة 2005؟","en":"How is a cash allowance paid instead of company group transport taxed under Law No. 91 of 2005?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نصّت الفقرة (ب) من البند (5) من المادة (13) من القانون صراحةً على إعفاء ميزة النقل الجماعي للعاملين أو ما يقابلها من تكلفة، بشرط أن تكون عينية وجماعية. فإذا كانت لدى المنشأة سيارات لنقل العاملين، فإن تكلفة نقلهم لا تُعد ميزة لهم ولا تخضع للضريبة؛ وكذلك إذا استأجرت سيارات من الغير لنقل العاملين نقلًا جماعيًّا، وهذا هو المقصود بعبارة «أو ما يقابلها من تكلفة». أما إذا صرفت الجهة لأي من العاملين مبالغ في صورة بدل نقدي مقابل ميزة النقل الجماعي، فإن هذا المبلغ يُعد ميزة نقدية لمن يحصل عليه ويخضع للضريبة على المرتبات وما في حكمها."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Article 13(5)(b) expressly exempts group transport provided to employees, or its cost, provided it is in kind and collective. If the company runs its own vehicles to transport staff, or hires vehicles from a third party for group transport, the cost is not a taxable benefit; that is what “or its cost” means. If the company instead pays an employee a cash allowance in place of group transport, that amount is a cash benefit subject to salary tax."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 11, true, $j${"ar":"ما المعاملة الضريبية لما يتقاضاه العاملون من حصص الأرباح التي يتقرر توزيعها قانونًا؟","en":"How is employees' statutory profit share taxed?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نصّ البند (6) من المادة (13) من القانون صراحةً على إعفاء حصة العاملين من الأرباح التي يتقرر توزيعها طبقًا للقانون، مع مراعاة أن هذه الحصة لا تُعد من التكاليف واجبة الخصم بالنسبة للشركة أو المنشأة عند تحديد وعائها الضريبي."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Article 13(6) expressly exempts employees' share of profits distributed in accordance with the law. That share is not a deductible cost for the company when its own taxable base is determined."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 12, true, $j${"ar":"ما المعاملة الضريبية لما يتقاضاه رؤساء وأعضاء مجالس الإدارة من مكافآت العضوية وبدلاتها في شركات الأموال؟","en":"How are board membership fees and allowances in capital companies taxed?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"لم يتضمن القانون نصًّا بخضوع ما يتقاضاه رؤساء وأعضاء مجالس الإدارة من مكافآت العضوية أو بدلاتها في شركات الأموال للضريبة على المرتبات وما في حكمها أو غيرها من الضرائب، مع مراعاة أن هذه المكافآت والبدلات لا تُعد من التكاليف واجبة الخصم عند تحديد الوعاء الضريبي للشركة طبقًا للبند (4) من المادة (52) من القانون رقم 91 لسنة 2005."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Law contains no provision subjecting board chairs' and members' membership fees or allowances in capital companies to salary tax or any other tax. However, under Article 52(4) of Law No. 91 of 2005, these fees and allowances are not deductible costs when the company's taxable base is determined."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 13, true, $j${"ar":"ما المعاملة الضريبية لما يتقاضاه رؤساء وأعضاء مجالس الإدارة المساهمون من حصص الأرباح وأرباح الأسهم الموزعة، ومقابل الحضور الذي يُدفع للمساهمين لحضور الجمعية العامة، في ظل القانون رقم 91 لسنة 2005؟","en":"How are profit shares, dividends and general-assembly attendance fees paid to shareholder board members taxed under Law No. 91 of 2005?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"لم يتضمن القانون نصًّا بخضوع هذه الحصص أو الأرباح الموزعة أو مقابل الحضور للضريبة على المرتبات وما في حكمها أو غيرها من الضرائب، مع مراعاة أن حصص الأرباح وأرباح الأسهم الموزعة ومقابل الحضور الذي يُدفع للمساهمين لحضور الجمعية العامة لا تُعد من التكاليف واجبة الخصم عند تحديد وعاء الضريبة بالنسبة للشركة."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Law contains no provision subjecting these profit shares, dividends or attendance fees to salary tax or any other tax. They are, however, not deductible costs when the company's taxable base is determined."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 14, true, $j${"ar":"ما المعاملة الضريبية لما يتقاضاه رؤساء وأعضاء مجالس الإدارة غير المساهمين في شركات القطاع العام وقطاع الأعمال العام من مرتبات ومكافآت؟","en":"How are salaries and bonuses paid to non-shareholder board members of public-sector and public-business-sector companies taxed?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"قرر القانون خضوع ما يحصل عليه رؤساء وأعضاء مجالس الإدارة غير المساهمين في شركات القطاع العام وقطاع الأعمال العام من مرتبات ومكافآت للضريبة على المرتبات وما في حكمها، شأنهم شأن باقي العاملين الخاضعين للضريبة."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"They are subject to salary tax, in the same way as any other taxable employee."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 15, true, $j${"ar":"ما المعاملة الضريبية لما يتقاضاه رؤساء وأعضاء مجالس الإدارة والمديرون في شركات الأموال من مرتبات ومكافآت مقابل العمل الإداري؟","en":"How are salaries and bonuses paid to board members and managers of capital companies for management work taxed?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"قرر القانون خضوع ما يحصل عليه رؤساء وأعضاء مجالس الإدارة والمديرون في شركات الأموال مقابل عملهم الإداري للضريبة على المرتبات وما في حكمها، شأنهم شأن باقي العاملين، ودون تحديد حد أقصى لهذه المبالغ أو لعدد هؤلاء الأعضاء."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"They are subject to salary tax like any other employee, with no cap on the amounts or on the number of such members."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 16, true, $j${"ar":"ما المعاملة الضريبية للمقابل النقدي لرصيد الإجازات الذي يُصرف للعاملين عند انتهاء الخدمة بسبب الوفاة أو الاستقالة أو الإحالة إلى المعاش؟","en":"How is cash paid for unused leave on termination of service (death, resignation or retirement) taxed?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"يُعفى ما يتقاضاه العاملون من مقابل نقدي لرصيد الإجازات عند انتهاء الخدمة، سواء بسبب الوفاة أو الاستقالة أو الإحالة إلى المعاش، من الضريبة على المرتبات وما في حكمها طبقًا للقانون رقم 232 لسنة 1996."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cash paid for an accrued leave balance on termination of service, whether through death, resignation or retirement, is exempt from salary tax under Law No. 232 of 1996."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 17, true, $j${"ar":"هل تُعد التكاليف الفعلية التي يتطلبها أداء العامل لمهام وظيفته من الإيرادات الخاضعة للضريبة؟","en":"Are actual costs an employee necessarily incurs to do their job taxable income?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"لا، فالتكاليف الفعلية التي يتطلبها بالضرورة أداء العامل لوظيفته لا تدخل ضمن الإيرادات الخاضعة للضريبة على المرتبات وما في حكمها، إذ تُعد مقابل تكلفة فعلية وفقًا للأحكام العامة للقانون."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. Actual costs necessarily incurred in performing the job are not part of income subject to salary tax; under the general provisions of the Law they are treated as reimbursement of an actual cost."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 18, true, $j${"ar":"هل يتمتع المحال إلى المعاش الذي يعمل لدى أي جهة بالإعفاءات الواردة بالمادتين (7) و(13) من القانون رقم 91 لسنة 2005 عن المبالغ التي يتقاضاها من جهة عمله؟","en":"Does a retiree who takes up employment benefit from the exemptions in Articles 7 and 13 of Law No. 91 of 2005?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"العامل الذي يلتحق بعمل بعد إحالته إلى المعاش يخضع ما يحصل عليه مقابل عمله للضريبة على المرتبات شأنه شأن باقي العاملين، ويتمتع بالشريحة المعفاة والإعفاء الشخصي وفقًا للقانون، مع مراعاة أن يظل ما يحصل عليه من المعاش غير خاضع للضريبة، وتُعد الجهة التي يعمل بها جهة عمله الأصلية."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes. A retiree who takes up new employment is taxed on their earnings like any other employee and receives the exempt bracket and personal allowance under the Law. Their pension remains non-taxable, and the new employer is treated as their main employer."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 19, true, $j${"ar":"ما أسعار الضريبة على صافي الإيراد الخاضع للضريبة على المرتبات وما في حكمها؟","en":"What rates apply to net taxable income from salaries and similar payments?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"الأسعار طبقًا لنص المادة (8) من القانون رقم 91 لسنة 2005:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"أكثر من 5000 جنيه حتى 20000 جنيه: 10%."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"أكثر من 20000 جنيه حتى 40000 جنيه: 15%."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"أكثر من 40000 جنيه: 20%."}]}]}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Under Article 8 of Law No. 91 of 2005 as originally enacted:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Over EGP 5,000 up to EGP 20,000: 10%."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Over EGP 20,000 up to EGP 40,000: 15%."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Over EGP 40,000: 20%."}]}]}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 20, true, $j${"ar":"ما نسبة مقابل التأخير المستحق على ما لم يقم أصحاب الأعمال أو الملتزمون بدفع الإيراد بتوريده في الميعاد؟ ومتى يُستحق؟","en":"What late-payment charge applies when employers or payers fail to remit tax on time, and when does it start?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"يُستحق مقابل التأخير من اليوم التالي لنهاية المهلة المحددة للتوريد، ويُحسب على أساس سعر الائتمان والخصم المعلن من البنك المركزي مضافًا إليه 2%."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The late-payment charge accrues from the day after the remittance deadline and is calculated at the Central Bank of Egypt's announced credit and discount rate plus 2%."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 21, true, $j${"ar":"هل يتمتع العامل أو الموظف الذي يعمل جزءًا من السنة بالشريحة المعفاة والإعفاء الشخصي (5000 و4000 جنيه) كاملين أم بنسبة مدة الحصول على الإيراد؟","en":"Does an employee who works only part of the year receive the full exempt bracket and personal allowance (EGP 5,000 and 4,000), or a pro-rata amount?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"يستحق الممول (العامل أو الموظف) الذي يعمل جزءًا من السنة الإعفاءات الضريبية المذكورة بنسبة مدة العمل إلى السنة، وفقًا لأحكام المواد (7) و(8) و(10) من القانون."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A pro-rata amount. Under Articles 7, 8 and 10 of the Law, an employee who works part of the year receives these exemptions in proportion to the period worked."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 22, true, $j${"ar":"من المسؤول عن توريد الضريبة إلى المصلحة؟","en":"Who is responsible for remitting the tax to the Tax Authority?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"المسؤول عن توريد الضريبة إلى المصلحة هم أصحاب الأعمال والملتزمون بدفع الإيرادات الخاضعة للضريبة، وذلك بحجز مبلغ مما يكون عليهم دفعه تحت حساب الضريبة وفقًا لما تحدده اللائحة التنفيذية، ويتم التوريد إلى مأمورية الضرائب المختصة خلال الخمسة عشر يومًا الأولى من كل شهر عن الدفعات التي تمت في الشهر السابق. وإذا كان صاحب العمل أو الملتزم بدفع الإيراد الخاضع للضريبة غير مقيم في مصر أو لم يكن له فيها مركز أو منشأة، تقع مسؤولية توريد الضريبة على مستحق الإيراد."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Employers and payers of taxable income. They withhold tax on account from the amounts they pay, as set out in the Executive Regulations, and remit it to the competent tax office within the first 15 days of each month for payments made in the previous month. If the employer or payer is not resident in Egypt and has no office or establishment there, the recipient of the income is responsible for remitting the tax."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 23, true, $j${"ar":"ما التزامات صاحب العمل تجاه المصلحة، وتجاه الموظف أو العامل؟","en":"What are an employer's obligations to the Tax Authority and to its employees?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"التزامات صاحب العمل تجاه المصلحة:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"أن يحجز مما يكون عليه دفعه مبلغًا تحت حساب الضريبة ويورّده خلال 15 يومًا من الشهر التالي."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"أن يسدد فروق الضريبة الناشئة عن الفحص، دون إخلال بحقه في الرجوع على الممول بما هو مدين به."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"أن يقدّم إقرارًا ربع سنوي إلى المصلحة في يناير وأبريل ويوليو وأكتوبر."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"أما التزامه تجاه الموظف أو العامل فهو أن يعطيه، بناءً على طلبه، كشفًا يبيّن اسمه ومبلغ الدخل ونوعه وقيمة الضريبة المحجوزة."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To the Tax Authority, the employer must:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Withhold tax on account from amounts it pays and remit it within 15 days of the following month."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pay any tax differences arising on examination, without prejudice to its right to recover them from the employee."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"File a quarterly return in January, April, July and October."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"To the employee, the employer must provide on request a statement showing the employee's name, the amount and type of income, and the tax withheld."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 24, true, $j${"ar":"ما العقوبة المقررة على الامتناع عن تقديم الإقرار الضريبي في الحالات التي يلتزم فيها الموظف بتقديمه؟","en":"What is the penalty for failing to file a tax return where an employee is required to file?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نصّت المادة (135) من القانون على المعاقبة بغرامة لا تقل عن ألفي جنيه ولا تجاوز عشرة آلاف جنيه لكل من امتنع عن تقديم الإقرار الضريبي."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Article 135 of the Law provides for a fine of not less than EGP 2,000 and not more than EGP 10,000 for anyone who fails to file a tax return."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 25, true, $j${"ar":"ما العقوبة المقررة في حالة امتناع أصحاب الأعمال أو الملتزمين بدفع الإيراد عن استقطاع الضريبة أو خصمها أو توريدها في المواعيد القانونية؟","en":"What is the penalty where employers or payers fail to withhold, deduct or remit tax on time?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نصّت المادة (135) من القانون على المعاقبة بغرامة لا تقل عن ألفي جنيه ولا تجاوز عشرة آلاف جنيه لكل من امتنع عن تقديم الإقرار الضريبي."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The original answer repeats the previous one: Article 135 of the Law provides for a fine of not less than EGP 2,000 and not more than EGP 10,000 for anyone who fails to file a tax return. This answer is awaiting review by SCO."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 26, true, $j${"ar":"ما المعاملة الضريبية للعلاوات الخاصة التي تقرر منحها للموظف عند حساب الضريبة على المرتبات وما في حكمها للأجر الأساسي؟","en":"How are special allowances (al-ʿilawat al-khassa) treated when calculating salary tax on basic pay?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"تضمنت الفقرة الأولى من المادة (13) من القانون حكمًا مفاده عدم الإخلال بالإعفاءات الضريبية الأخرى المقررة بقوانين خاصة؛ وحيث إن هذه العلاوات معفاة بنص صريح في القوانين التي تقررها، فإنها تُعفى من ضريبة المرتبات وفقًا لهذه القوانين."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The first paragraph of Article 13 preserves tax exemptions granted under special laws. Because these special allowances are expressly exempted by the laws that grant them, they are exempt from salary tax under those laws."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 27, true, $j${"ar":"ما المعاملة الضريبية للأجور المتغيرة المنصرفة مقابل العلاوات الخاصة التي ضُمّت إلى المرتب الأساسي؟","en":"How are variable wages paid in respect of special allowances merged into basic pay taxed?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"العلاوات الخاصة معفاة بموجب قوانين منحها، سواء أضيفت إلى المرتب الأساسي أم لم تُضف؛ إلا أن الأجور المتغيرة المنصرفة مقابل العلاوات الخاصة التي أضيفت إلى المرتب الأساسي تخضع للضريبة ولا تتمتع بالإعفاء المقرر للعلاوة، وفقًا لما انتهى إليه رأي الجمعية العمومية لقسمي الفتوى والتشريع بمجلس الدولة ووافقت عليه مصلحة الضرائب."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Special allowances are exempt under the laws that grant them, whether or not they have been merged into basic pay. However, variable wages paid in respect of special allowances that have been merged into basic pay are taxable and do not share the allowance's exemption. This follows an opinion of the General Assembly of the Fatwa and Legislation Departments of the State Council, adopted by the Tax Authority."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 28, true, $j${"ar":"ما المعاملة الضريبية لما يحصل عليه أعضاء السلكين الدبلوماسي والقنصلي والمنظمات الدولية وغيرهم من الممثلين الدبلوماسيين الأجانب في نطاق عملهم الرسمي؟","en":"How is income received by foreign diplomatic and consular staff and international-organisation officials in the course of their official duties taxed?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"تضمن البند (7) من المادة (13) من القانون حكمًا بإعفاء ما يحصل عليه أعضاء السلكين الدبلوماسي والقنصلي والمنظمات الدولية وغيرهم من الممثلين الدبلوماسيين الأجانب من المرتبات وما في حكمها في نطاق عملهم الرسمي، بشرط المعاملة بالمثل وفي حدود تلك المعاملة."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Article 13(7) exempts salaries and similar payments received by members of the diplomatic and consular corps, international organisations and other foreign diplomatic representatives in the course of their official duties, subject to reciprocity and to the extent of it."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 29, true, $j${"ar":"ما المعاملة الضريبية لما يحصل عليه العاملون في السفارات والقنصليات والمنظمات الدولية الكائنة في جمهورية مصر العربية؟","en":"How are local staff of embassies, consulates and international organisations in Egypt taxed?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"لم يتضمن القانون نصًّا بإعفاء ما يحصل عليه العاملون في السفارات والقنصليات والمنظمات الدولية من غير أعضاء السلكين الدبلوماسي والقنصلي والمنظمات الدولية من المرتبات وما في حكمها؛ وبذلك يخضع ما يحصلون عليه للضريبة على المرتبات وما في حكمها عن أدائهم الخدمة في مصر، مع مراعاة أحكام اتفاقيات تجنب الازدواج الضريبي."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Law contains no exemption for employees of embassies, consulates and international organisations who are not themselves members of the diplomatic or consular corps or of the organisation. Their salaries for services performed in Egypt are therefore subject to salary tax, taking into account any applicable double-taxation treaty."}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date),
($s$payroll-tax$s$, 30, true, $j${"ar":"ما حدود الإعفاء المقرر لاشتراكات العاملين في صناديق التأمين الخاصة المنشأة طبقًا للقانون رقم 54 لسنة 1975، وأقساط التأمين على الحياة والتأمين الصحي على الممول لمصلحته أو لمصلحة زوجه أو أولاده القُصّر، وأي أقساط تأمين لاستحقاق معاش؟","en":"What are the limits on the exemption for contributions to private insurance funds (Law No. 54 of 1975), life and health insurance premiums for the taxpayer, spouse or minor children, and pension insurance premiums?"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"تضمن البندان (3) و(4) من المادة (13) من القانون الإعفاء من:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"اشتراكات العاملين في صناديق التأمين الخاصة التي تنشأ طبقًا لأحكام قانون صناديق التأمين الخاصة رقم 54 لسنة 1975."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"أقساط التأمين على الحياة والتأمين الصحي على الممول لمصلحته أو لمصلحة زوجه أو أولاده القُصّر، وأي أقساط تأمين لاستحقاق معاش."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"واشترطت المادة نفسها ألا يزيد مجموع ما يُعفى للممول منها على 15% من صافي الإيراد أو ثلاثة آلاف جنيه في السنة أيهما أكبر، ولا يجوز إعفاء الاشتراكات والأقساط ذاتها من أي دخل آخر منصوص عليه في المادة (6) من القانون. وتطبيقًا لذلك:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إذا قلّت نسبة الـ15% عن 3000 جنيه، يكون الحد الأقصى لما يُستقطع من الإيراد الخاضع للضريبة 3000 جنيه، ويُستقطع المبلغ المدفوع أو 3000 جنيه أيهما أقل."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إذا زادت نسبة الـ15% على 3000 جنيه، يكون الحد الأقصى لما يُستقطع المبلغ المدفوع أو 15% من الدخل أيهما أقل."}]}]}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Article 13(3) and (4) exempt:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Employee contributions to private insurance funds established under Private Insurance Funds Law No. 54 of 1975."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Life and health insurance premiums paid for the taxpayer, their spouse or minor children, and any premiums paid to secure a pension."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The same Article caps the total exemption at 15% of net income or EGP 3,000 a year, whichever is greater, and the same contributions and premiums cannot also be exempted against any other income listed in Article 6. The legacy answer then explains the cap as follows:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where 15% of income is less than EGP 3,000, the maximum deduction is EGP 3,000, and the deduction is the amount paid or EGP 3,000, whichever is lower."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where 15% of income exceeds EGP 3,000, the deduction is the amount paid or 15% of income, whichever is lower."}]}]}]}]}}$j$::jsonb, $j${"ar":"قانون الضريبة على الدخل رقم 91 لسنة 2005 (بحسب نص الإجابة الأصلية)","en":"Income Tax Law No. 91 of 2005 (as originally written)"}$j$::jsonb, $s$2021-01-01$s$::date)
) v where not exists (select 1 from public.faqs);

