insert into public.services ("slug", "legacy_slug", "sort", "published", "icon", "image", "name", "summary", "intro", "body", "highlights", "seo") values
($s$external-audit$s$, $s$finance-auditing$s$, 1, true, $s$audit$s$, null, $j${"ar":"المراجعة الخارجية","en":"External Audit"}$j$::jsonb, $j${"ar":"مراجعة القوائم المالية وفق معايير المراجعة المصرية والدولية للوصول إلى تأكيد معقول بخلوّها من التحريف الجوهري.","en":"Audits of financial statements under Egyptian and International Standards on Auditing, giving reasonable assurance that they are free from material misstatement."}$j$::jsonb, $j${"ar":"تعرّف جمعية المحاسبة الأمريكية المراجعة بأنها «عملية منظمة ومنهجية لجمع الأدلة والقرائن المتعلقة بنتائج الأنشطة والأحداث الاقتصادية وتقييمها بموضوعية، لتحديد مدى توافق هذه النتائج مع المعايير المقررة، وإبلاغ الأطراف المعنية بنتائج المراجعة».","en":"The American Accounting Association defines auditing as “a systematic process of objectively obtaining and evaluating evidence regarding assertions about economic actions and events, to ascertain the degree of correspondence between those assertions and established criteria, and communicating the results to interested users.”"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نُجري المراجعة طبقًا لمعايير المراجعة الدولية ومعايير المراجعة المصرية، ووفقًا للقوانين واللوائح المصرية ذات الصلة، للوصول إلى تأكيد معقول بأن القوائم المالية لا تنطوي على أخطاء أو تحريف جوهري. وتشمل أعمال المراجعة ما يلي:"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"نطاق أعمال المراجعة"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إجراء مراجعة اختبارية للسجلات المحاسبية بالمنشأة ومستنداتها طبقًا لإجراءات المراجعة المخططة في ضوء ظروف المنشأة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"فحص وتقييم المبادئ والسياسات المحاسبية المتبعة بالمنشأة، والمخصصات التي تحددها إدارة المنشأة بطريق التقدير."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تقييم عام لطريقة عرض القوائم المالية وما تتضمنه من إفصاحات وإيضاحات."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"المراجعة الدورية خلال العام"}]},{"type":"paragraph","content":[{"type":"text","text":"عمل مراجعة دورية خلال العام تتضمن فحص وتقييم النظم المحاسبية ونظم الرقابة الداخلية المطبقة بالمنشأة، والقيام بجميع الاختبارات اللازمة للتحقق من سلامة تطبيق تلك النظم وكفاءتها، وبذل العناية المهنية اللازمة لاكتشاف الأخطاء والمخالفات الهامة التي قد يكون لها تأثير على القوائم المالية للمنشأة."}]},{"type":"callout","attrs":{"tone":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"في حالة وجود ملاحظات هامة تسفر عنها المراجعة الدورية، يتم إرسالها في تقرير لإدارة المنشأة يتضمن هذه الملاحظات وتوصياتنا لمعالجتها، وذلك بعد مناقشتها مع إدارة المنشأة."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"المراجعة النهائية في نهاية العام"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"فحص ومطابقة الحسابات الختامية مع السجلات المحاسبية."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"التحقق من وجود الأصول التي تظهر بالميزانية وقيمتها، والمبالغ الخاصة بالالتزامات والمخصصات، للتحقق من أن الميزانية تعبّر بوضوح عن حقيقة المركز المالي."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"فحص قائمة الدخل للتأكد من أنها تُظهر صحة نتيجة أعمال المنشأة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"التأكد من أن الإفصاح والعرض بالإيضاحات المتممة للقوائم المالية تم وفقًا للمبادئ المحاسبية المتعارف عليها وفي ظل القوانين واللوائح المعمول بها."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إعداد تقرير مراقب الحسابات على القوائم المالية في نهاية السنة المالية."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"عند الانتهاء من أعمال المراجعة النهائية، إذا تبيّن وجود ملاحظات متعلقة بمراجعة القوائم المالية أو أي ملاحظات أخرى بخلاف ما ورد بتقرير المراجعة الدورية، يتم إرسال تقرير يتضمن ملاحظاتنا عن أعمال المراجعة النهائية بعد مناقشته مع إدارة المنشأة."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We conduct our audits in accordance with International Standards on Auditing, Egyptian Standards on Auditing and the applicable Egyptian laws and regulations, to obtain reasonable assurance that the financial statements are free from material error or misstatement. Our audit work covers:"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scope of the audit"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Test examination of the entity's accounting records and supporting documents, following audit procedures planned around the entity's circumstances."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review and evaluation of the accounting principles and policies the entity applies, and of the provisions management determines by estimate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An overall evaluation of how the financial statements are presented, including their disclosures and notes."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Interim audit during the year"}]},{"type":"paragraph","content":[{"type":"text","text":"A periodic review during the year, examining and evaluating the entity's accounting systems and internal controls. We perform the tests needed to confirm those systems are applied soundly and efficiently, and exercise due professional care to detect significant errors and irregularities that could affect the financial statements."}]},{"type":"callout","attrs":{"tone":"info"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Where the interim audit raises significant findings, we discuss them with management and then issue a management letter setting out the findings and our recommendations."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Year-end audit"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Examining the final accounts and reconciling them with the accounting records."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Verifying the existence and value of the assets on the balance sheet, and the amounts of liabilities and provisions, so that the balance sheet fairly presents the financial position."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Examining the income statement to confirm it fairly presents the results of operations."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirming that disclosures and notes to the financial statements follow generally accepted accounting principles and applicable laws and regulations."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Issuing the auditor's report on the financial statements at the end of the financial year."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"On completing the year-end audit, if there are findings on the financial statements, or other matters beyond those reported at the interim stage, we discuss them with management and issue a report on the year-end audit work."}]}]}}$j$::jsonb, $j${"ar":["معايير المراجعة المصرية والدولية","مراجعة دورية ونهائية","خطاب للإدارة بالملاحظات والتوصيات","تقرير مراقب الحسابات"],"en":["Egyptian & International Standards on Auditing","Interim and year-end audit","Management letter with recommendations","Statutory auditor's report"]}$j$::jsonb, $j${"ar":{"title":"المراجعة الخارجية ومراقبة الحسابات","description":"مراجعة القوائم المالية وفق معايير المراجعة المصرية والدولية: مراجعة دورية ونهائية، وتقييم نظم الرقابة الداخلية، وتقرير مراقب الحسابات."},"en":{"title":"External Audit","description":"Financial statement audits under Egyptian and International Standards on Auditing: interim and year-end audit, internal control review and the statutory auditor's report."}}$j$::jsonb),
($s$accounting$s$, $s$accounting-services$s$, 2, true, $s$ledger$s$, null, $j${"ar":"الخدمات المحاسبية","en":"Accounting & Bookkeeping"}$j$::jsonb, $j${"ar":"من تأسيس النظام المحاسبي ومسك الدفاتر إلى القوائم المالية ومؤشرات الأداء والإقرارات الضريبية والمرتبات.","en":"From setting up your accounting system and keeping the books to financial statements, KPIs, tax returns and payroll."}$j$::jsonb, $j${"ar":"النظام المالي والمحاسبي في أي شركة من أهم عوامل نجاحها، فهو الوسيلة الأساسية لقياس نتائجها؛ وكلما كان لديك نظام محاسبي جيد أصبح اتخاذ القرارات الحالية والمستقبلية أسهل.","en":"A company's financial and accounting system is one of the keys to its success: it is how results are measured. The better the system, the easier it becomes to make decisions today and plan for tomorrow."}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"لذلك نوفّر لعملائنا خدمات محاسبية متكاملة:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تأسيس النظام المحاسبي."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"مسك الدفاتر والتسجيل بها."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إعداد التسويات البنكية والائتمانية وتسويات المخزون."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إعداد القوائم المالية ومؤشرات الأداء للشركات."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إعداد الإقرارات الضريبية وفقًا للقوانين الضريبية المختلفة في مصر."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إعداد كشوف المرتبات وحساب قيمة التأمينات الاجتماعية الشهرية."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"يقوم بكل ذلك مختصون لديهم الخبرة العلمية والعملية الكافية. ونهدف من خلال هذه الخدمات إلى أن نرفع عن عملائنا عبء هذا الدور المهم، الذي قد يكلّفك كثيرًا من الوقت والجهد والمال إذا اعتمدت على فريق غير مؤهل أو غير متابع لأحدث التطورات في معايير المحاسبة والقوانين الضريبية المحلية."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"That is why we offer a complete set of accounting services:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Designing and setting up the accounting system."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bookkeeping and maintaining the books of account."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bank, credit and inventory reconciliations."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Financial statements and performance indicators."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tax returns under Egypt's various tax laws."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Payroll and monthly social insurance calculations."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"All of this is handled by specialists with solid academic and practical experience. Our aim is to take this demanding work off your hands. Relying on a team that is not qualified, or not current with developments in accounting standards and local tax law, can cost a business a great deal of time, effort and money."}]}]}}$j$::jsonb, $j${"ar":["تأسيس النظام المحاسبي","مسك الدفاتر والتسويات","القوائم المالية ومؤشرات الأداء","المرتبات والتأمينات الاجتماعية"],"en":["Accounting system set-up","Bookkeeping & reconciliations","Financial statements & KPIs","Payroll & social insurance"]}$j$::jsonb, $j${"ar":{"title":"الخدمات المحاسبية ومسك الدفاتر","description":"تأسيس النظم المحاسبية ومسك الدفاتر والتسويات البنكية والقوائم المالية والإقرارات الضريبية وكشوف المرتبات والتأمينات الاجتماعية."},"en":{"title":"Accounting & Bookkeeping Services","description":"Accounting system set-up, bookkeeping, reconciliations, financial statements, tax returns, payroll and social insurance for companies in Egypt."}}$j$::jsonb),
($s$company-formation$s$, $s$establishing-companies$s$, 3, true, $s$building$s$, null, $j${"ar":"تأسيس الشركات","en":"Company Formation"}$j$::jsonb, $j${"ar":"تأسيس جميع أشكال الشركات وفروع الشركات الأجنبية، والقيد في السجلات الرسمية، وشؤون الشركات والتراخيص.","en":"Formation of every type of company and foreign branch, registration with the official registers, corporate affairs and licensing."}$j$::jsonb, $j${"ar":"يقدّم المكتب خدمات الاستثمار وتأسيس الشركات من خلال نخبة من المتخصصين، وتشمل:","en":"Our specialists handle investment and company-formation work end to end, including:"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تأسيس جميع أنواع شركات الأموال وشركات الأشخاص والمنشآت الفردية، وفروع الشركات الأجنبية، ومكاتب التمثيل ومكاتب الاتصال والمكاتب العلمية."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"الاستشارات في مجال شؤون الشركات وجميع القوانين المرتبطة بها."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تحويل الشكل القانوني للشركات."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"الاندماج أو التقسيم والتصفية."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"قيد الشركات وتسجيلها في: السجل التجاري، والسجل الصناعي، والهيئة العامة للرقابة المالية، والبورصة، وسجل الوكلاء التجاريين، وسجل المصدّرين والمستوردين، وسجل التأجير التمويلي، وسجل مقاولي القطاع الخاص، والاتحاد المصري لمقاولي التشييد والبناء."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تعديل النظام الأساسي للشركات وتوفيق أوضاعها، وإعداد العقود والاتفاقيات الجانبية، وشهادات الأسهم وصكوكها والسندات، ومحاضر الجمعيات العامة للمساهمين ومجالس الإدارة، وسجلات المساهمين، ودفاتر الملكية والتنازلات."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"المساعدة في الحصول على تصاريح العمل والإقامة لغير المصريين."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"الحصول على التراخيص اللازمة للمشروعات والشركات، والمعاونة في حل مشكلاتها مع الجهات الحكومية وغير الحكومية."}]}]}]}]},"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Forming every type of company: joint-stock and limited liability companies, partnerships, sole proprietorships, branches of foreign companies, and representative, liaison and scientific offices."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Advice on corporate affairs and the laws that govern them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Changing a company's legal form."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mergers, demergers and liquidations."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Registration with the Commercial Register, the Industrial Register, the Financial Regulatory Authority, the Egyptian Exchange, the Commercial Agents Register, the Importers and Exporters Registers, the Financial Leasing Register, the Private Sector Contractors Register and the Egyptian Federation for Construction and Building Contractors."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Amending articles of association and regularising a company's status; drafting contracts and side agreements; share certificates, instruments and bonds; minutes of general assemblies and board meetings; shareholder registers, ownership ledgers and transfers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Obtaining work and residence permits for non-Egyptians."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Obtaining the licences projects and companies need, and resolving issues with government and non-government bodies."}]}]}]}]}}$j$::jsonb, $j${"ar":["جميع الأشكال القانونية","السجل التجاري والسجلات الرسمية","الاندماج والتقسيم والتصفية","تصاريح العمل والإقامة"],"en":["Every legal form","Commercial register & official registries","Mergers, demergers & liquidation","Work & residence permits"]}$j$::jsonb, $j${"ar":{"title":"تأسيس الشركات في مصر","description":"تأسيس شركات الأموال والأشخاص وفروع الشركات الأجنبية، والقيد في السجل التجاري والسجلات الرسمية، وتعديل الأنظمة الأساسية والتراخيص."},"en":{"title":"Company Formation in Egypt","description":"Company formation, foreign branches, commercial register and official registrations, corporate governance documents, licences and work permits in Egypt."}}$j$::jsonb),
($s$feasibility-studies$s$, $s$feasibility-studies$s$, 4, true, $s$chart$s$, null, $j${"ar":"دراسات الجدوى","en":"Feasibility Studies"}$j$::jsonb, $j${"ar":"دراسات جدوى اقتصادية تسويقية وفنية ومالية تنتهي بقرار واضح بقبول فكرة المشروع أو رفضها.","en":"Market, technical and financial feasibility studies that end in a clear decision on whether to proceed."}$j$::jsonb, $j${"ar":"دراسات الجدوى الاقتصادية من أهم العوامل وأكثرها تأثيرًا عند اختيار مشروع استثماري جديد؛ فهدفها الأساسي دراسة إمكانية قيام المشروع، وتحقيق أقصى عائد ممكن من الموارد المتاحة، وتحقيق أرباح أو عائد يفوق التكلفة المستثمرة، والوصول إلى قرار نهائي بقبول الفكرة أو رفضها.","en":"A feasibility study is one of the most important inputs when choosing a new investment. Its purpose is to test whether the project can be established, how to earn the best possible return on the resources available, and whether that return will exceed the capital invested, leading to a final decision to go ahead or not."}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"مراحل دراسة الجدوى الاقتصادية للمشروعات"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"الدراسة السوقية"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"مدى أهمية المشروع للسوق."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تحديد الفئات المستهدفة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تحديد المنافسين."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"قياس مدى استيعاب السوق للمنتج."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دراسة العرض والطلب على المنتج."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دراسة مصغّرة لأساليب التسويق المتبعة للمنتج، واقتراح أنسب الطرق التسويقية للوصول إلى المبيعات المستهدفة."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"الدراسة الفنية"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دراسة واختيار موقع المشروع."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تخطيط العملية الإنتاجية ومراحل الإنتاج."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"اختيار معدات الإنتاج وتوصيفها."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تحديد دورة التشغيل."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دراسة التكاليف الثابتة والمتغيرة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تقدير التكاليف الاستثمارية المطلوبة للمشروع."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"الدراسة المالية"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"دراسة الإيرادات وأسعار البيع المقترحة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"إعداد قوائم الدخل وقوائم التدفقات النقدية المستقبلية للمشروع."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"المؤشرات المالية والاقتصادية"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تحليل الربحية والسيولة وفترة استرداد رأس المال."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"تقييم المشروع"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"توصيات عامة عن المشروع من وجهة النظر الاقتصادية والاجتماعية."}]}]}]}]},"en":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The stages of an economic feasibility study"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Market study"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How important the project is to the market."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Defining the target segments."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Identifying competitors."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Measuring how much of the product the market can absorb."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Analysing supply and demand for the product."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A short review of how the product is currently marketed, with recommendations on the best channels to reach the target sales."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Technical study"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Assessing and selecting the project site."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Planning the production process and its stages."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Selecting and specifying production equipment."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Defining the operating cycle."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Analysing fixed and variable costs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Estimating the investment the project requires."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Financial study"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revenue analysis and proposed selling prices."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Projected income statements and cash-flow statements for the project."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Financial and economic indicators"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Profitability, liquidity and payback-period analysis."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Project evaluation"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Overall recommendations on the project from an economic and social standpoint."}]}]}]}]}}$j$::jsonb, $j${"ar":["دراسة سوقية","دراسة فنية","دراسة مالية وتدفقات نقدية","الربحية وفترة الاسترداد"],"en":["Market study","Technical study","Financial study & cash flows","Profitability & payback"]}$j$::jsonb, $j${"ar":{"title":"دراسات الجدوى الاقتصادية","description":"دراسات جدوى سوقية وفنية ومالية للمشروعات: تحليل السوق والمنافسين، والتكاليف الاستثمارية، والتدفقات النقدية، والربحية وفترة الاسترداد."},"en":{"title":"Feasibility Studies","description":"Market, technical and financial feasibility studies: competitor and demand analysis, investment costs, projected cash flows, profitability and payback period."}}$j$::jsonb),
($s$project-finance$s$, $s$project-financing$s$, 5, true, $s$finance$s$, null, $j${"ar":"تمويل المشروعات","en":"Project Finance"}$j$::jsonb, $j${"ar":"توفير بدائل التمويل المناسبة لكل مرحلة من البنوك والصناديق والمستثمرين، مع إدارة النقدية ومتابعتها.","en":"Sourcing the right financing for each stage from banks, funds and investors, with ongoing cash management."}$j$::jsonb, $j${"ar":"الحصول على التمويل المناسب في كل مرحلة من مراحل المشروع من أهم المشكلات التي تواجه أي مستثمر، وخصوصًا في المشروعات الناشئة؛ لذلك نساعد عملاءنا بتوفير العديد من البدائل والفرص التمويلية، سواء من المؤسسات المالية المتخصصة أو من جهات التمويل الخاصة، مثل:","en":"Securing the right financing at every stage of a project is one of the hardest problems any investor faces, especially for start-ups. We help clients by identifying a range of financing options, from specialised financial institutions and from private sources, including:"}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"التمويل من البنوك والصناديق الخاصة:","marks":[{"type":"bold"}]},{"type":"text","text":" نتأكد من استيفاء الشروط التي تطلبها جهة التمويل، ونوفّر جميع المستندات المطلوبة، ونتواصل مع الجهة الممولة، ونيسّر جميع الإجراءات حتى الحصول على التمويل أو القرض المطلوب."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"التمويل الخاص:","marks":[{"type":"bold"}]},{"type":"text","text":" من خلال إيجاد مستثمرين أو شركاء لديهم رأس المال ويرغبون في الاستثمار في الشركات الناشئة، وبخاصة المشروعات المبتكرة والمميزة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"صناديق الاستثمار:","marks":[{"type":"bold"}]},{"type":"text","text":" للشركات الاستثمارية التي لديها فائض مالي وترغب في استثماره في مشروع قائم يحقق لها عائدًا جيدًا دون الدخول في أعباء الإدارة."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"إدارة النقدية والمتابعة"}]},{"type":"paragraph","content":[{"type":"text","text":"بالإضافة إلى ذلك نتولّى إدارة النقدية ومتابعة العميل بصفة دورية ومستمرة، للتأكد من كيفية إدارة التمويل داخل المشروع، ومدى الالتزام بالسداد، والعلاقات مع البنوك؛ كما ندرس ونراقب الفروق المتوقعة وغير المتوقعة بين التدفقات النقدية الداخلة والخارجة، ونساعد العملاء في التعامل مع النقدية الزائدة بالطريقة التي تخدم مصلحة المنشأة مستقبلًا."}]}]},"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bank and private-fund financing:","marks":[{"type":"bold"}]},{"type":"text","text":" we confirm the lender's requirements are met, prepare all the required documents, liaise with the financing institution and manage the process through to drawdown."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Private investment:","marks":[{"type":"bold"}]},{"type":"text","text":" introducing investors or partners with capital who want to invest in start-ups, particularly innovative and distinctive projects."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Investment funds:","marks":[{"type":"bold"}]},{"type":"text","text":" for investment companies with surplus capital that want a return from an established project without taking on its management."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cash management and monitoring"}]},{"type":"paragraph","content":[{"type":"text","text":"We also manage cash and follow up with clients regularly to track how financing is used within the project, repayment discipline and banking relationships. We monitor expected and unexpected gaps between cash inflows and outflows, and help clients deploy surplus cash in the way that best serves the business."}]}]}}$j$::jsonb, $j${"ar":["البنوك والصناديق","المستثمرون والشركاء","صناديق الاستثمار","إدارة النقدية"],"en":["Banks & private funds","Investors & partners","Investment funds","Cash management"]}$j$::jsonb, $j${"ar":{"title":"تمويل المشروعات","description":"توفير بدائل التمويل من البنوك والصناديق والمستثمرين، وتجهيز ملفات التمويل، ومتابعة إدارة النقدية والتدفقات النقدية للمشروعات."},"en":{"title":"Project Finance Advisory","description":"Financing from banks, private funds and investors, preparation of financing files, and ongoing cash and cash-flow management for projects."}}$j$::jsonb),
($s$tax$s$, $s$tax-services$s$, 6, true, $s$tax$s$, null, $j${"ar":"الخدمات الضريبية","en":"Tax Services"}$j$::jsonb, $j${"ar":"الفحص الضريبي، وإعداد الإقرارات الضريبية بجميع أنواعها وتقديمها، والاستشارات الضريبية.","en":"Tax examinations, preparation and filing of every type of tax return, and tax advisory."}$j$::jsonb, $j${"ar":"نتعامل مع جميع أنواع الفحص الضريبي في مختلف مراحله، ونُعدّ الإقرارات الضريبية ونقدّمها، ونقدّم الاستشارات الضريبية من خلال خبراء متخصصين.","en":"We handle every type of tax examination at every stage, prepare and file tax returns, and advise through specialist tax experts."}$j$::jsonb, $j${"ar":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"الفحص الضريبي"}]},{"type":"paragraph","content":[{"type":"text","text":"لدينا فريق متخصص للتعامل مع جميع أنواع الفحص الضريبي في مختلف مراحله، بالإضافة إلى علاقاتنا الممتدة منذ أكثر من 25 عامًا مع معظم مأموريات الضرائب في مصر، مما يُيسّر مهمتنا في توفيق أوضاع عملائنا لدى مصلحة الضرائب المصرية."}]},{"type":"paragraph","content":[{"type":"text","text":"ويشمل ذلك فحص الإقرار الضريبي والمستندات المؤيدة له، والحضور أمام المأموريات واللجان المختلفة لتقديم جميع الردود والإجابة عن الاستفسارات التي قد يطلبها موظفو المصلحة، توفيرًا للوقت على الممول والمأمورية، وللحصول على أفضل النتائج الممكنة بما يتوافق مع القوانين الضريبية والتعليمات التنفيذية."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"إعداد الإقرارات الضريبية وتقديمها"}]},{"type":"paragraph","content":[{"type":"text","text":"يُعدّ إعداد الإقرارات الضريبية من الأمور المهمة التي تترتب عليها آثار مستقبلية قد تُلحق ضررًا كبيرًا بأي شركة؛ فإذا لم تكن الإقرارات المقدمة إلى المأمورية متوافقة مع القوانين والتعليمات التنفيذية الدورية، فقد تظهر عند الفحص فروق ضريبية غير مسددة بالإضافة إلى مقابل التأخير المقرر قانونًا. لذا يجب الحرص عند إعداد إقرارك الضريبي والاطلاع على التعليمات التنفيذية، حتى تتجنب الخلاف مع مأمورية الضرائب وما قد يسببه من أزمة حقيقية لشركتك."}]},{"type":"paragraph","content":[{"type":"text","text":"ونحن في المكتب الاستشاري المتخصص نوفّر هذه الخدمة لعملائنا ونتابعهم باستمرار، فنُعدّ ونقدّم الإقرارات الضريبية بجميع أنواعها:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ضريبة الدخل."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ضريبة القيمة المضافة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ضريبة الخصم والإضافة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ضريبة الدمغة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ضريبة كسب العمل (المرتبات)."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"وذلك وفقًا للقوانين المتبعة والتعليمات التنفيذية، لضمان أفضل النتائج في الفحص الضريبي والحفاظ على استقرار الشركات."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"الاستشارات الضريبية"}]},{"type":"paragraph","content":[{"type":"text","text":"نقدّم الاستشارات الضريبية من خلال خبرائنا المتخصصين في مختلف المراحل الضريبية، ومن خلال علاقتنا بمصلحة الضرائب، لتضمن أنك تسير على الطريق الصحيح وتتجنب الأخطاء التي قد تكلّف شركتك الكثير."}]}]},"en":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tax examinations"}]},{"type":"paragraph","content":[{"type":"text","text":"Our specialist team handles every type of tax examination at every stage. Our relationships with most tax offices across Egypt go back more than 25 years, which makes it easier to settle our clients' positions with the Egyptian Tax Authority."}]},{"type":"paragraph","content":[{"type":"text","text":"This covers examining the tax return and its supporting documents, and attending tax offices and appeal committees to provide every response and answer any query the Authority's staff raise. It saves time for the taxpayer and the tax office alike, and secures the best possible outcome within the tax laws and executive regulations."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Preparing and filing tax returns"}]},{"type":"paragraph","content":[{"type":"text","text":"Tax returns have consequences that can seriously harm a company years later. If a return does not comply with the law and the periodic executive instructions, an examination may reveal unpaid tax differences plus statutory late-payment charges. That is why a return needs careful preparation against the current instructions, to avoid a dispute with the tax office and a real crisis for the business."}]},{"type":"paragraph","content":[{"type":"text","text":"At SCO we provide this service and stay in regular contact with our clients, preparing and filing every type of return:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Corporate and personal income tax."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Value added tax (VAT)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Withholding and advance-payment tax."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stamp duty."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Payroll (salaries) tax."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Every return follows the applicable laws and executive regulations, to secure the best result at examination and keep the business on a stable footing."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tax advisory"}]},{"type":"paragraph","content":[{"type":"text","text":"Our specialists advise at every stage of the tax cycle and draw on our working relationship with the Tax Authority, so you can be confident you are on the right path and avoid mistakes that could cost your company dearly."}]}]}}$j$::jsonb, $j${"ar":["الفحص الضريبي واللجان","ضريبة الدخل والقيمة المضافة","الخصم والإضافة والدمغة","الاستشارات الضريبية"],"en":["Tax examinations & appeals","Income tax & VAT","Withholding tax & stamp duty","Tax advisory"]}$j$::jsonb, $j${"ar":{"title":"الخدمات الضريبية والفحص الضريبي","description":"الفحص الضريبي والحضور أمام المأموريات واللجان، وإعداد وتقديم إقرارات ضريبة الدخل والقيمة المضافة والخصم والإضافة والدمغة والمرتبات، والاستشارات الضريبية."},"en":{"title":"Tax Services in Egypt","description":"Tax examinations and appeals, preparation and filing of income tax, VAT, withholding, stamp duty and payroll tax returns, and tax advisory in Egypt."}}$j$::jsonb)
